/* Dark-mode-first, OKLCH color palette */

:root {
  /* Colors — OKLCH */
  --bg-base:        oklch(11% 0.012 240);   /* #0d1117 equivalent */
  --bg-surface:     oklch(15% 0.014 240);   /* card background */
  --bg-elevated:    oklch(18% 0.016 240);   /* elevated panels */
  --bg-hover:       oklch(21% 0.018 240);
  --border:         oklch(28% 0.020 240);
  --border-subtle:  oklch(22% 0.016 240);

  --text-primary:   oklch(95% 0.004 240);
  --text-secondary: oklch(65% 0.012 240);
  --text-tertiary:  oklch(48% 0.014 240);

  /* Accent — electric cyan/green */
  --accent:         oklch(72% 0.19 165);   /* electric green */
  --accent-dim:     oklch(62% 0.16 165);
  --accent-subtle:  oklch(22% 0.06 165);

  /* Blue accent (brand link color) */
  --blue:           oklch(62% 0.13 255);
  --blue-dim:       oklch(52% 0.11 255);
  --blue-subtle:    oklch(19% 0.05 255);

  /* Purple accent for Agents */
  --purple:         oklch(65% 0.17 295);
  --purple-subtle:  oklch(18% 0.05 295);

  /* Amber for Storefronts */
  --amber:          oklch(75% 0.17 75);
  --amber-subtle:   oklch(19% 0.06 75);

  /* Typography */
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', monospace;

  /* Spacing scale */
  --sp-1: 4px;
  --sp-2: 8px;
  --sp-3: 12px;
  --sp-4: 16px;
  --sp-5: 20px;
  --sp-6: 24px;
  --sp-8: 32px;
  --sp-10: 40px;
  --sp-12: 48px;
  --sp-16: 64px;
  --sp-20: 80px;
  --sp-24: 96px;

  /* Border radius */
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --r-xl: 20px;

  /* Shadows */
  --shadow-card: 0 1px 3px oklch(0% 0 0 / 0.4), 0 0 0 1px var(--border);
  --shadow-elevated: 0 4px 24px oklch(0% 0 0 / 0.5), 0 0 0 1px var(--border);
  --glow-accent: 0 0 20px oklch(72% 0.19 165 / 0.15);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-mid: 250ms ease;

  /* Layout */
  --sidebar-w: 260px;
  --content-max: 880px;
  --page-max: 1280px;
}

/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  background: var(--bg-base);
  color: var(--text-primary);
  font-family: var(--font-sans);
  font-size: 15px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--blue); text-decoration: none; transition: color var(--transition-fast); }
a:hover { color: oklch(72% 0.15 255); }

img { display: block; max-width: 100%; }

code, pre {
  font-family: var(--font-mono);
  font-size: 0.875em;
}

/* ===== SCROLLBAR ===== */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-base); }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }

/* ===== TYPOGRAPHY ===== */
h1 { font-size: clamp(2rem, 5vw, 3.5rem); font-weight: 800; line-height: 1.1; letter-spacing: -0.03em; }
h2 { font-size: clamp(1.5rem, 3vw, 2.25rem); font-weight: 700; line-height: 1.2; letter-spacing: -0.02em; }
h3 { font-size: 1.25rem; font-weight: 600; line-height: 1.3; letter-spacing: -0.01em; }
h4 { font-size: 1rem; font-weight: 600; line-height: 1.4; }
p { color: var(--text-secondary); }

.label {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-tertiary);
}

/* ===== TOP NAVIGATION ===== */
.topnav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: oklch(11% 0.012 240 / 0.85);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border-subtle);
  height: 60px;
  display: flex;
  align-items: center;
}

.topnav-inner {
  max-width: var(--page-max);
  margin: 0 auto;
  padding: 0 var(--sp-6);
  width: 100%;
  display: flex;
  align-items: center;
  gap: var(--sp-6);
}

.topnav-logo {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  font-weight: 700;
  font-size: 1rem;
  color: var(--text-primary);
  white-space: nowrap;
  flex-shrink: 0;
}

.topnav-logo svg { flex-shrink: 0; }

.topnav-links {
  display: flex;
  align-items: center;
  gap: var(--sp-1);
  flex: 1;
}

.topnav-link {
  padding: var(--sp-2) var(--sp-3);
  border-radius: var(--r-sm);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: color var(--transition-fast), background var(--transition-fast);
  white-space: nowrap;
}
.topnav-link:hover { color: var(--text-primary); background: var(--bg-surface); }
.topnav-link.active { color: var(--text-primary); }

.topnav-right {
  display: flex;
  align-items: center;
  gap: var(--sp-3);
  flex-shrink: 0;
}

.btn-search {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  padding: var(--sp-2) var(--sp-3);
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--r-sm);
  color: var(--text-tertiary);
  font-size: 0.8125rem;
  cursor: pointer;
  transition: all var(--transition-fast);
}
.btn-search:hover { border-color: var(--border); color: var(--text-secondary); background: var(--bg-elevated); }

.btn-login {
  padding: var(--sp-2) var(--sp-4);
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--r-sm);
  color: var(--text-primary);
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition-fast);
  white-space: nowrap;
}
.btn-login:hover { border-color: var(--blue); color: var(--blue); }

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-2);
  padding: var(--sp-3) var(--sp-5);
  border-radius: var(--r-sm);
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition-fast);
  border: none;
  text-decoration: none;
  white-space: nowrap;
}

.btn-primary {
  background: var(--accent);
  color: oklch(10% 0.01 165);
}
.btn-primary:hover {
  background: oklch(78% 0.2 165);
  color: oklch(10% 0.01 165);
  box-shadow: var(--glow-accent);
}

.btn-secondary {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border);
}
.btn-secondary:hover { background: var(--bg-surface); border-color: var(--text-secondary); color: var(--text-primary); }

.btn-ghost {
  background: transparent;
  color: var(--blue);
  padding: 0;
}
.btn-ghost:hover { color: oklch(72% 0.15 255); }

.btn-sm {
  padding: var(--sp-2) var(--sp-3);
  font-size: 0.8125rem;
}

/* ===== CONTAINER ===== */
.container {
  max-width: var(--page-max);
  margin: 0 auto;
  padding: 0 var(--sp-6);
}

/* ===== SECTION ===== */
.section { padding: var(--sp-20) 0; }
.section-sm { padding: var(--sp-12) 0; }

.section-header { margin-bottom: var(--sp-10); }
.section-header .label { margin-bottom: var(--sp-3); }
.section-header h2 { margin-bottom: var(--sp-3); }
.section-header p { max-width: 600px; }

/* ===== GRID ===== */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: var(--sp-4); }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--sp-4); }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--sp-4); }

/* ===== CARDS ===== */
.card {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--r-lg);
  padding: var(--sp-6);
  transition: border-color var(--transition-mid), background var(--transition-mid), box-shadow var(--transition-mid);
}
.card:hover {
  border-color: var(--border);
  background: var(--bg-elevated);
  box-shadow: var(--shadow-elevated);
}

.card-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--r-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--sp-4);
  font-size: 1.25rem;
}

.card h3 { margin-bottom: var(--sp-2); }
.card p { font-size: 0.875rem; margin-bottom: var(--sp-4); }

/* ===== PRODUCT CARDS ===== */
.product-card {
  position: relative;
  overflow: hidden;
  border-radius: var(--r-xl);
  padding: var(--sp-8);
  border: 1px solid var(--border);
  transition: all var(--transition-mid);
  display: flex;
  flex-direction: column;
  min-height: 280px;
}
.product-card::before {
  content: '';
  position: absolute;
  inset: 0;
  opacity: 0;
  transition: opacity var(--transition-mid);
}
.product-card:hover::before { opacity: 1; }

.product-card-apps { background: linear-gradient(135deg, var(--bg-surface) 0%, var(--blue-subtle) 100%); }
.product-card-apps:hover { border-color: var(--blue-dim); box-shadow: 0 8px 32px oklch(62% 0.13 255 / 0.12); }

.product-card-storefronts { background: linear-gradient(135deg, var(--bg-surface) 0%, var(--amber-subtle) 100%); }
.product-card-storefronts:hover { border-color: oklch(60% 0.13 75); box-shadow: 0 8px 32px oklch(75% 0.17 75 / 0.1); }

.product-card-agents { background: linear-gradient(135deg, var(--bg-surface) 0%, var(--purple-subtle) 100%); }
.product-card-agents:hover { border-color: oklch(55% 0.13 295); box-shadow: 0 8px 32px oklch(65% 0.17 295 / 0.12); }

.product-card-number {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-tertiary);
  margin-bottom: var(--sp-6);
}
.product-card h3 { font-size: 1.5rem; margin-bottom: var(--sp-3); }
.product-card p { font-size: 0.9375rem; flex: 1; }
.product-card .card-cta { margin-top: var(--sp-6); }

/* ===== CODE BLOCKS ===== */
.code-wrapper {
  background: oklch(8% 0.01 240);
  border: 1px solid var(--border);
  border-radius: var(--r-md);
  overflow: hidden;
}

.code-tabs {
  display: flex;
  border-bottom: 1px solid var(--border);
  padding: 0 var(--sp-4);
  gap: 0;
}

.code-tab {
  padding: var(--sp-3) var(--sp-4);
  font-family: var(--font-mono);
  font-size: 0.8125rem;
  color: var(--text-tertiary);
  cursor: pointer;
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
  margin-bottom: -1px;
  background: none;
  border-top: none;
  border-left: none;
  border-right: none;
}
.code-tab:hover { color: var(--text-secondary); }
.code-tab.active { color: var(--accent); border-bottom-color: var(--accent); }

.code-panel { display: none; padding: var(--sp-5); }
.code-panel.active { display: block; }

.code-panel pre {
  color: oklch(88% 0.04 165);
  font-size: 0.875rem;
  line-height: 1.7;
  overflow-x: auto;
  white-space: pre;
}

.code-prompt { color: var(--accent); user-select: none; }
.code-cmd { color: var(--text-primary); }
.code-pkg { color: oklch(78% 0.14 165); }
.code-comment { color: var(--text-tertiary); }

/* ===== ACCORDION ===== */
.accordion { border: 1px solid var(--border); border-radius: var(--r-lg); overflow: hidden; }

.accordion-item { border-bottom: 1px solid var(--border); }
.accordion-item:last-child { border-bottom: none; }

.accordion-header {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--sp-5) var(--sp-6);
  background: var(--bg-surface);
  cursor: pointer;
  border: none;
  text-align: left;
  color: var(--text-primary);
  font-size: 1rem;
  font-weight: 600;
  font-family: var(--font-sans);
  transition: background var(--transition-fast);
  gap: var(--sp-4);
}
.accordion-header:hover { background: var(--bg-elevated); }
.accordion-header.open { background: var(--bg-elevated); }

.accordion-chevron {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  color: var(--text-tertiary);
  transition: transform var(--transition-mid);
}
.accordion-header.open .accordion-chevron { transform: rotate(180deg); }

.accordion-body {
  display: none;
  padding: var(--sp-6);
  background: oklch(13% 0.013 240);
  border-top: 1px solid var(--border-subtle);
}
.accordion-body.open { display: block; }

.accordion-steps {
  display: flex;
  flex-direction: column;
  gap: var(--sp-5);
  margin-bottom: var(--sp-6);
}

.accordion-step {
  display: flex;
  gap: var(--sp-4);
  align-items: flex-start;
}

.step-num {
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent-subtle);
  border: 1px solid oklch(40% 0.10 165);
  color: var(--accent);
  font-size: 0.75rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 2px;
}

.step-text { font-size: 0.9375rem; color: var(--text-secondary); }

/* ===== HERO ===== */
.hero {
  padding: var(--sp-24) 0 var(--sp-20);
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: -200px;
  left: 50%;
  transform: translateX(-50%);
  width: 800px;
  height: 600px;
  background: radial-gradient(ellipse, oklch(62% 0.13 255 / 0.08) 0%, transparent 70%);
  pointer-events: none;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-2);
  padding: var(--sp-1) var(--sp-3);
  background: var(--accent-subtle);
  border: 1px solid oklch(40% 0.10 165);
  border-radius: 100px;
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--accent);
  margin-bottom: var(--sp-6);
}

.hero h1 { margin-bottom: var(--sp-5); }
.hero p { font-size: 1.125rem; max-width: 620px; margin-bottom: var(--sp-8); color: var(--text-secondary); }

.hero-ctas {
  display: flex;
  flex-wrap: wrap;
  gap: var(--sp-3);
}

/* ===== DIVIDER ===== */
.divider {
  height: 1px;
  background: var(--border-subtle);
  margin: 0;
}

/* ===== COMMUNITY LINKS ===== */
.community-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--sp-4);
}

.community-card {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--r-lg);
  padding: var(--sp-5);
  display: flex;
  flex-direction: column;
  gap: var(--sp-2);
  transition: all var(--transition-fast);
  cursor: pointer;
}
.community-card:hover { border-color: var(--blue-dim); background: var(--bg-elevated); }
.community-card h4 { color: var(--blue); }
.community-card p { font-size: 0.8125rem; color: var(--text-tertiary); }

/* ===== LAUNCH SECTION ===== */
.launch-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--sp-5);
}

.launch-card {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--r-xl);
  padding: var(--sp-8);
  display: flex;
  flex-direction: column;
  gap: var(--sp-3);
}
.launch-card h3 { margin-bottom: var(--sp-2); }
.launch-card p { font-size: 0.9375rem; flex: 1; }

/* ===== DOCS LAYOUT (with sidebar) ===== */
.docs-layout {
  display: flex;
  min-height: calc(100vh - 60px);
}

.docs-sidebar {
  width: var(--sidebar-w);
  flex-shrink: 0;
  border-right: 1px solid var(--border);
  padding: var(--sp-6) 0;
  position: sticky;
  top: 60px;
  height: calc(100vh - 60px);
  overflow-y: auto;
  transition: width var(--transition-mid), opacity var(--transition-mid);
  background: var(--bg-base);
}

.docs-sidebar.collapsed {
  width: 0;
  opacity: 0;
  overflow: hidden;
}

.sidebar-toggle {
  position: fixed;
  left: var(--sidebar-w);
  top: 50%;
  transform: translateY(-50%);
  z-index: 50;
  width: 20px;
  height: 40px;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-left: none;
  border-radius: 0 var(--r-sm) var(--r-sm) 0;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: left var(--transition-mid);
  color: var(--text-tertiary);
}
.sidebar-toggle:hover { color: var(--text-primary); background: var(--bg-hover); }
.docs-sidebar.collapsed ~ .sidebar-toggle { left: 0; }

.sidebar-section { margin-bottom: var(--sp-6); }
.sidebar-section-title {
  padding: var(--sp-2) var(--sp-5);
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-tertiary);
  margin-bottom: var(--sp-1);
}

.sidebar-link {
  display: flex;
  align-items: center;
  padding: var(--sp-2) var(--sp-5);
  font-size: 0.875rem;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
  border-left: 2px solid transparent;
}
.sidebar-link:hover { color: var(--text-primary); background: var(--bg-surface); border-left-color: var(--border); }
.sidebar-link.active { color: var(--text-primary); background: var(--bg-surface); border-left-color: var(--accent); }

.docs-main {
  flex: 1;
  min-width: 0;
  padding: var(--sp-10) var(--sp-12);
  max-width: 100%;
}

.docs-main.expanded { padding-left: var(--sp-16); }

/* ===== AGENT DIAGRAM ===== */
.agent-diagram {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--sp-4);
  margin: var(--sp-8) 0;
}

.agent-actor {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--r-lg);
  padding: var(--sp-5) var(--sp-4);
  text-align: center;
  transition: all var(--transition-mid);
}
.agent-actor:hover { border-color: var(--purple); box-shadow: 0 4px 20px oklch(65% 0.17 295 / 0.15); }

.agent-actor-icon {
  font-size: 2rem;
  margin-bottom: var(--sp-3);
}
.agent-actor h4 { margin-bottom: var(--sp-2); }
.agent-actor p { font-size: 0.8125rem; }

/* ===== TAG ===== */
.tag {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1);
  padding: 2px var(--sp-2);
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 600;
}
.tag-coming-soon { background: oklch(30% 0.08 75); color: var(--amber); border: 1px solid oklch(40% 0.10 75); }
.tag-new { background: var(--accent-subtle); color: var(--accent); border: 1px solid oklch(40% 0.10 165); }

/* ===== FOOTER ===== */
.footer {
  border-top: 1px solid var(--border-subtle);
  padding: var(--sp-16) 0 var(--sp-10);
  background: oklch(10% 0.011 240);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: var(--sp-10);
  margin-bottom: var(--sp-12);
}

.footer-brand { display: flex; flex-direction: column; gap: var(--sp-4); }
.footer-brand p { font-size: 0.875rem; max-width: 280px; }

.footer-col h4 {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-tertiary);
  margin-bottom: var(--sp-4);
}
.footer-col a {
  display: block;
  font-size: 0.875rem;
  color: var(--text-secondary);
  padding: var(--sp-1) 0;
  transition: color var(--transition-fast);
}
.footer-col a:hover { color: var(--text-primary); }

.footer-bottom {
  padding-top: var(--sp-6);
  border-top: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--sp-4);
}
.footer-bottom p { font-size: 0.8125rem; color: var(--text-tertiary); }

/* ===== GLASS PANEL ===== */
.glass {
  background: oklch(15% 0.014 240 / 0.6);
  backdrop-filter: blur(12px);
  border: 1px solid oklch(28% 0.02 240 / 0.5);
}

/* ===== INLINE CODE ===== */
.inline-code {
  font-family: var(--font-mono);
  font-size: 0.875em;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 1px 6px;
  color: var(--accent);
}

/* ===== MOBILE HAMBURGER ===== */
.mobile-menu-btn {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  padding: var(--sp-2);
  background: none;
  border: none;
  margin-left: auto;
}
.mobile-menu-btn span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--text-secondary);
  border-radius: 2px;
  transition: all var(--transition-fast);
}

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .community-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: var(--sp-8); }
  .agent-diagram { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .topnav-links { display: none; }
  .topnav-links.mobile-open {
    display: flex;
    flex-direction: column;
    position: fixed;
    top: 60px;
    left: 0;
    right: 0;
    background: var(--bg-base);
    border-bottom: 1px solid var(--border);
    padding: var(--sp-4);
    z-index: 99;
    gap: var(--sp-2);
  }
  .mobile-menu-btn { display: flex; }

  .grid-3 { grid-template-columns: 1fr; }
  .grid-2 { grid-template-columns: 1fr; }
  .launch-grid { grid-template-columns: 1fr; }

  .hero { padding: var(--sp-16) 0 var(--sp-12); }
  .hero-ctas { flex-direction: column; }

  .docs-sidebar { display: none; }
  .docs-sidebar.mobile-open {
    display: block;
    position: fixed;
    top: 60px;
    left: 0;
    bottom: 0;
    z-index: 50;
    width: 260px;
    border-right: 1px solid var(--border);
    background: var(--bg-base);
  }
  .sidebar-toggle { display: none; }
  .docs-main { padding: var(--sp-6); }

  .footer-grid { grid-template-columns: 1fr; }
  .agent-diagram { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 480px) {
  .container { padding: 0 var(--sp-4); }
  h1 { font-size: 1.875rem; }
  .agent-diagram { grid-template-columns: 1fr 1fr; }
  .community-grid { grid-template-columns: 1fr; }
}
